/// <summary>
/// Return state of <c>initFromPriceDiscAdmTrans</c> variable. True if record is created by Copy button
/// </summary>
/// <returns>True if record is created by Copy button; Otherwise false</returns>
public boolean isRecordCopy()
{
    return initFromPriceDiscAdmTrans;
}

public void updateDesign(InventDimFormDesignUpdate mode)
{
    next updateDesign(mode);

    boolean isPricingEnabled = PriceDiscAdmName::find(callerpriceDiscAdmTable.JournalName).PriceDiscPriceAttributeEnable;

    if (isPricingEnabled && FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        InventDimParm   inventDimParm       = InventDimParm::allInventDim();
        InventDimParm   inventDimParmEnable = inventDimParm.data();

        inventDimParm.initProductDimensionsAllGroups();

        inventDimFormSetup.parmDimParmEnabled(inventDimParmEnable);
        inventDimFormSetup.parmDontShowDisabled(false);
        inventDimFormSetup.parmDimParmVisibleGrid(inventDimParm);
        inventDimFormSetup.formSetControls(true);
    }
}

[FormControlEventHandler(formControlStr(PriceDiscAdm, InventoryDimension_configId), FormControlEventType::Lookup)]
public static void InventoryDimension_configId_OnLookup(FormControl sender, FormControlEventArgs e)
{
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource  = query.addDataSource(tableNum(EcoResConfiguration));
    SysTableLookup          tableLookup = SysTableLookup::newParameters(tablenum(EcoResConfiguration), sender);
    tableLookup.addLookupfield(fieldnum(EcoResConfiguration, Name));
    tableLookup.parmQuery(query);
    tableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    ce.CancelSuperCall();
}

